import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../../shared/widgets/app_scaffold.dart';
import '../../../dashboard/presentation/providers/dashboard_providers.dart';
class ProductsScreen extends ConsumerStatefulWidget { const ProductsScreen({super.key}); @override ConsumerState<ProductsScreen> createState() => _ProductsState(); }
class _ProductsState extends ConsumerState<ProductsScreen> { final search = TextEditingController(); @override Widget build(BuildContext context) { final products = ref.watch(productsProvider(search.text)); return AppScaffold(title: 'Products & inventory', child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [Expanded(child: TextField(controller: search, onChanged: (_) => setState(() {}), decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Search products'))), const SizedBox(width: 12), FilledButton.icon(onPressed: () {}, icon: const Icon(Icons.add), label: const Text('New product'))]), const SizedBox(height: 18), products.when(data: (items) => Card(child: Column(children: items.map((p) => ListTile(title: Text(p.name), subtitle: Text('${p.category} • Cost ZMW ${p.costPrice.toStringAsFixed(2)}'), leading: CircleAvatar(child: Text(p.name.substring(0, 1))), trailing: Column(mainAxisAlignment: MainAxisAlignment.center, crossAxisAlignment: CrossAxisAlignment.end, children: [Text('ZMW ${p.sellingPrice.toStringAsFixed(2)}', style: const TextStyle(fontWeight: FontWeight.bold)), Text('${p.stockQuantity} in stock', style: TextStyle(color: p.isLowStock ? Colors.red : Colors.grey))])).toList())), error: (e, _) => Text('Could not load products: $e'), loading: () => const CircularProgressIndicator())])); } }
